<?php use App\Core\Security;?><h4>دسته‌بندی محصولات</h4><form method="post" class="card card-body mb-3"><input type="hidden" name="_csrf" value="<?=Security::e(Security::csrf())?>"><div class="row g-2"><div class="col-md-4"><input name="name" class="form-control" placeholder="نام دسته" required></div><div class="col-md-6"><input name="description" class="form-control" placeholder="توضیحات"></div><div class="col-md-2"><button class="btn btn-primary w-100">ثبت</button></div></div></form><div class="table-responsive"><table class="table table-bordered"><thead><tr><th>نام</th><th>توضیحات</th><th>وضعیت</th><th>عملیات</th></tr></thead><tbody><?php foreach($categories as $r):?><tr><td colspan="3"><form method="post" action="/pricing/public/admin/categories/<?=(int)$r['id']?>" class="row g-2"><input type="hidden" name="_csrf" value="<?=Security::e(Security::csrf())?>"><div class="col-md-4"><input name="name" value="<?=Security::e($r['name'])?>" class="form-control" required></div><div class="col-md-5"><input name="description" value="<?=Security::e($r['description'])?>" class="form-control"></div><div class="col-md-3"><?=$r['is_active']?'فعال':'غیرفعال'?></div></form></td><td><form method="post" action="/pricing/public/admin/categories/<?=(int)$r['id']?>/status"><input type="hidden" name="_csrf" value="<?=Security::e(Security::csrf())?>"><button class="btn btn-sm btn-outline-secondary">تغییر وضعیت</button></form></td></tr><?php endforeach;?></tbody></table></div>